@Test
public void testPartialComplex() throws TException {
    int id = 1;
    int numItems = 10;
    TestStruct ts1 = testData.createTestStruct(id, numItems);
    byte[] bytesBinary = serde.serializeBinary(ts1);
    byte[] bytesCompact = serde.serializeCompact(ts1);
    List<String> fieldNames = Arrays.asList("byteField", "i16Field", "i32Field", "i64Field", "doubleField", "stringField", "enumField", "binaryField", // List fields
    "byteList", "i16List", "i32List", "i64List", "doubleList", "stringList", "enumList", "listList", "setList", "mapList", "structList", "binaryList", // Set fields
    "byteSet", "i16Set", "i32Set", "i64Set", "doubleSet", "stringSet", "enumSet", "listSet", "setSet", "mapSet", "structSet", "binarySet", // Map fields
    "byteMap", "i16Map", "i32Map", "i64Map", "doubleMap", "stringMap", "enumMap", "listMap", "setMap", "mapMap", "structMap", "binaryMap", // Struct field
    "structField");
    StringBuilder sb = new StringBuilder();
    TDeserializer partialBinaryDeserializer = new TDeserializer(TestStruct.class, fieldNames, binaryProtocolFactory);
    TDeserializer partialCompactDeserializer = new TDeserializer(TestStruct.class, fieldNames, compactProtocolFactory);
    PartialThriftComparer comparer = new PartialThriftComparer(partialBinaryDeserializer.getMetadata());
    TestStruct ts2 = (TestStruct) partialBinaryDeserializer.partialDeserializeObject(bytesBinary);
    validatePartialComplex(ts1, ts2, id, numItems);
    assertTrue(comparer.areEqual(ts1, ts2, sb), sb::toString);
    ts2 = (TestStruct) partialCompactDeserializer.partialDeserializeObject(bytesCompact);
    validatePartialComplex(ts1, ts2, id, numItems);
    assertTrue(comparer.areEqual(ts1, ts2, sb), sb::toString);
}

