    // Should not throw.
    test = new ThriftField("foo");
    test = new ThriftField("foo", Collections.singletonList(new ThriftField("bar")));
    testFields = ThriftField.fromNames(Collections.singletonList("foo"));
    // Verify it throws.
    assertThrows(IllegalArgumentException.class, () -> new ThriftField(null, Collections.emptyList()), "'name' must not be null");
    assertThrows(IllegalArgumentException.class, () -> new ThriftField("foo", null), "'fields' must not be null");
    assertThrows(IllegalArgumentException.class, () -> ThriftField.fromNames(null), "'fieldNames' must not be null");
    assertThrows(IllegalArgumentException.class, () -> ThriftField.fromNames(Collections.emptyList()), "'fieldNames' must have at least one element");
