@Test
public void testBadPassword() throws Exception {
    TProtocolFactory protocolFactory = new TBinaryProtocol.Factory();
    TProcessor processor = new ThriftTest.Processor<>(new TestHandler());
    startServer(processor, protocolFactory);
    TSocket socket = new TSocket(HOST, PORT);
    socket.setTimeout(SOCKET_TIMEOUT);
    try (TSaslClientTransport client = new TSaslClientTransport(TestTSaslTransports.WRAPPED_MECHANISM, TestTSaslTransports.PRINCIPAL, TestTSaslTransports.SERVICE, TestTSaslTransports.HOST, TestTSaslTransports.WRAPPED_PROPS, new TestSaslCallbackHandler("bad_password"), socket)) {
        TTransportException error = assertThrows(TTransportException.class, client::open, "Client should fail with sasl negotiation.");
        TSaslNegotiationException serverSideError = new TSaslNegotiationException(AUTHENTICATION_FAILURE, "Authentication failed with " + TestTSaslTransports.WRAPPED_MECHANISM);
        assertTrue(error.getMessage().contains(serverSideError.getSummary()), "Server should return error message \"" + serverSideError.getSummary() + "\"");
    } finally {
        stopServer();
    }
}

